From 2f73b24a7a36f42acbbf842a938648f3b525ba61 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:47:46 +0100
Subject: [PATCH] vpn/openconnect: don't freeze kded when reconnecting during
 SSO login

Connecting again while the SSO web view was open waited for the worker,
which was blocked on the web view, so kded hung. Release the web view,
cancel the login and reuse the web profile so the new login page loads.

BUG: 524348
---
 vpn/openconnect/openconnectauth.cpp           | 19 ++++++++++++++-----
 .../openconnectauthworkerthread.cpp           |  6 ++++++
 2 files changed, 20 insertions(+), 5 deletions(-)

diff --git a/vpn/openconnect/openconnectauth.cpp b/vpn/openconnect/openconnectauth.cpp
index a02b55b67..fa2fd6166 100644
--- a/vpn/openconnect/openconnectauth.cpp
+++ b/vpn/openconnect/openconnectauth.cpp
@@ -92,6 +92,7 @@ public:
     QByteArray tokenMode;
     Token token;
     QAtomicPointer<QSemaphore> waitForWebEngineFinish;
+    QWebEngineProfile *webEngineProfile = nullptr;
     OpenconnectWebAuthDialog *authDialog;

     enum LogLevels {
@@ -368,6 +369,10 @@ void OpenconnectAuthWidget::connectHost()
     Q_D(OpenconnectAuthWidget);

     d->userQuit = true;
+    QSemaphore *webEngineCancel = d->waitForWebEngineFinish.fetchAndStoreRelaxed(nullptr);
+    if (webEngineCancel) {
+        webEngineCancel->release();
+    }
     if (write(d->cancelPipes[1], "x", 1)) {
         // not a lot we can do
     }
@@ -642,22 +647,26 @@ void OpenconnectAuthWidget::openWebEngine(const char *loginUri, QSemaphore *wait
     Q_D(OpenconnectAuthWidget);
     d->waitForWebEngineFinish.storeRelease(waitForWebEngineFinish);
     auto webEngineView = new QWebEngineView(this);
-    QWebEngineProfile *profile = new QWebEngineProfile("plasma-nm-openconnect", this);
-    QString persistentStoragePath = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);
-    profile->setPersistentStoragePath(persistentStoragePath.append("/plasma-nm-openconnect"));
+    // Reuse the profile when the login is restarted, two profiles can not share the same storage
+    if (!d->webEngineProfile) {
+        d->webEngineProfile = new QWebEngineProfile("plasma-nm-openconnect", this);
+        QString persistentStoragePath = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);
+        d->webEngineProfile->setPersistentStoragePath(persistentStoragePath.append("/plasma-nm-openconnect"));
+        connect(d->webEngineProfile->cookieStore(), &QWebEngineCookieStore::cookieAdded, this, &OpenconnectAuthWidget::handleWebEngineCookie);
+    }
+    QWebEngineProfile *profile = d->webEngineProfile;

     if (d->ui.chkStorePlaintextCookies->isChecked()) {
         profile->setPersistentCookiesPolicy(QWebEngineProfile::AllowPersistentCookies);
     } else {
         profile->setPersistentCookiesPolicy(QWebEngineProfile::NoPersistentCookies);
     }
-    QWebEnginePage *page = new QWebEnginePage(profile, this);
+    QWebEnginePage *page = new QWebEnginePage(profile, webEngineView);
     QWebEngineCookieStore *cookieStore = profile->cookieStore();

     connect(webEngineView, &QWebEngineView::urlChanged, this, &OpenconnectAuthWidget::handleWebEngineUrl);
     connect(page, &QWebEnginePage::loadingChanged, this, &OpenconnectAuthWidget::handleWebEngineLoad);
     connect(page, &QWebEnginePage::webAuthUxRequested, this, &OpenconnectAuthWidget::handleWebAuthUxRequested);
-    connect(cookieStore, &QWebEngineCookieStore::cookieAdded, this, &OpenconnectAuthWidget::handleWebEngineCookie);
     cookieStore->loadAllCookies();

     webEngineView->setPage(page);
diff --git a/vpn/openconnect/openconnectauthworkerthread.cpp b/vpn/openconnect/openconnectauthworkerthread.cpp
index 7728f084a..a0f5cfab7 100644
--- a/vpn/openconnect/openconnectauthworkerthread.cpp
+++ b/vpn/openconnect/openconnectauthworkerthread.cpp
@@ -216,10 +216,16 @@ int OpenconnectAuthWorkerThread::openWebEngineP(__attribute__((unused)) struct o
                                                 const char *loginUri,
                                                 __attribute__((unused)) void *privdata)
 {
+    if (*m_userDecidedToQuit) {
+        return OC_FORM_RESULT_CANCELLED;
+    }
     QSemaphore waitForWebEngineFinish;

     Q_EMIT openWebEngine(loginUri, &waitForWebEngineFinish);
     waitForWebEngineFinish.acquire();
+    if (*m_userDecidedToQuit) {
+        return OC_FORM_RESULT_CANCELLED;
+    }

     return 0;
 }
